/*
 * Drive scipy's dnaupd_wrap in a tight C loop.
 * dnaupd_wrap(state_dict, resid, v, ipntr, workd, workl) -> None
 * We call it via the Python C API but avoid the per-iteration Python matvec.
 */

static void csr_matvec(npy_intp n, const npy_int32 *indptr, const npy_int32 *indices,
                       const double *data, const double *x, double *y) {
    for (npy_intp i = 0; i < n; i++) {
        double s = 0.0;
        npy_int32 start = indptr[i];
        npy_int32 end = indptr[i + 1];
        for (npy_int32 j = start; j < end; j++) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

static PyObject *py_arpack_loop(PyObject *self, PyObject *args) {
    PyObject *wrap;          /* dnaupd_wrap callable */
    PyObject *state;         /* dict */
    PyObject *resid_obj, *v_obj, *ipntr_obj, *workd_obj, *workl_obj;
    PyObject *indptr_obj, *indices_obj, *data_obj;
    if (!PyArg_ParseTuple(args, "OOOOOOOOO", &wrap, &state,
                          &resid_obj, &v_obj, &ipntr_obj, &workd_obj, &workl_obj,
                          &indptr_obj, &indices_obj, &data_obj)) {
        return NULL;
    }
    PyArrayObject *resid = (PyArrayObject *)PyArray_FROM_OTF(resid_obj, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *v = (PyArrayObject *)PyArray_FROM_OTF(v_obj, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *ipntr = (PyArrayObject *)PyArray_FROM_OTF(ipntr_obj, NPY_INT32, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *workd = (PyArrayObject *)PyArray_FROM_OTF(workd_obj, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *workl = (PyArrayObject *)PyArray_FROM_OTF(workl_obj, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *indptr_a = (PyArrayObject *)PyArray_FROM_OTF(indptr_obj, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *indices_a = (PyArrayObject *)PyArray_FROM_OTF(indices_obj, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *data_a = (PyArrayObject *)PyArray_FROM_OTF(data_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!resid || !v || !ipntr || !workd || !workl || !indptr_a || !indices_a || !data_a) {
        Py_XDECREF(resid); Py_XDECREF(v); Py_XDECREF(ipntr); Py_XDECREF(workd); Py_XDECREF(workl);
        Py_XDECREF(indptr_a); Py_XDECREF(indices_a); Py_XDECREF(data_a);
        return NULL;
    }

    npy_intp n = PyArray_SIZE((PyArrayObject *)resid);
    const npy_int32 *ip = (const npy_int32 *)PyArray_DATA(indptr_a);
    const npy_int32 *idx = (const npy_int32 *)PyArray_DATA(indices_a);
    const double *dat = (const double *)PyArray_DATA(data_a);
    double *wd = (double *)PyArray_DATA(workd);
    int *ipn = (int *)PyArray_DATA(ipntr);

    PyObject *ido_key = PyUnicode_FromString("ido");
    PyObject *info_key = PyUnicode_FromString("info");
    if (!ido_key || !info_key) {
        return NULL;
    }

    long long steps = 0;
    int info = 0;
    while (1) {
        PyObject *ret = PyObject_CallFunctionObjArgs(wrap, state, resid, v, ipntr, workd, workl, NULL);
        if (!ret) {
            Py_DECREF(ido_key); Py_DECREF(info_key);
            goto fail;
        }
        Py_DECREF(ret);
        steps++;
        PyObject *ido_obj = PyDict_GetItem(state, ido_key); /* borrowed */
        if (!ido_obj) {
            PyErr_SetString(PyExc_RuntimeError, "ido missing");
            goto fail_keys;
        }
        int ido = (int)PyLong_AsLong(ido_obj);
        if (ido == 1 || ido == -1 || ido == 5) {
            int x0 = ipn[0];
            int y0 = ipn[1];
            /* zero output then accumulate? our csr_matvec overwrites */
            csr_matvec(n, ip, idx, dat, wd + x0, wd + y0);
        } else if (ido == 2) {
            int x0 = ipn[0];
            int y0 = ipn[1];
            memcpy(wd + y0, wd + x0, sizeof(double) * (size_t)n);
        } else if (ido == 4) {
            PyErr_SetString(PyExc_RuntimeError, "ido 4 unexpected");
            goto fail_keys;
        } else {
            PyObject *info_obj = PyDict_GetItem(state, info_key);
            info = info_obj ? (int)PyLong_AsLong(info_obj) : -1;
            break;
        }
        if (steps > 5000000) {
            PyErr_SetString(PyExc_RuntimeError, "too many steps");
            goto fail_keys;
        }
    }
    Py_DECREF(ido_key); Py_DECREF(info_key);
    Py_DECREF(resid); Py_DECREF(v); Py_DECREF(ipntr); Py_DECREF(workd); Py_DECREF(workl);
    Py_DECREF(indptr_a); Py_DECREF(indices_a); Py_DECREF(data_a);
    return Py_BuildValue("Li", steps, info);

fail_keys:
    Py_DECREF(ido_key); Py_DECREF(info_key);
fail:
    Py_DECREF(resid); Py_DECREF(v); Py_DECREF(ipntr); Py_DECREF(workd); Py_DECREF(workl);
    Py_DECREF(indptr_a); Py_DECREF(indices_a); Py_DECREF(data_a);
    return NULL;
}

