static void csr_matvec(npy_intp n, const npy_int32 *indptr, const npy_int32 *indices,
                       const double *data, const double *x, double *y) {
    for (npy_intp i = 0; i < n; ++i) {
        double s = 0.0;
        npy_int32 a = indptr[i];
        npy_int32 b = indptr[i + 1];
        for (npy_int32 j = a; j < b; ++j) {
            s += data[j] * x[indices[j]];
        }
        y[i] = s;
    }
}

static PyObject *py_solve(PyObject *self, PyObject *args) {
    PyObject *wrap, *state;
    PyObject *resid_obj, *v_obj, *ipntr_obj, *workd_obj, *workl_obj;
    PyObject *indptr_obj, *indices_obj, *data_obj;
    PyObject *extract; /* callable params.extract */
    if (!PyArg_ParseTuple(args, "OOOOOOOOOO", &wrap, &state,
                          &resid_obj, &v_obj, &ipntr_obj, &workd_obj, &workl_obj,
                          &indptr_obj, &indices_obj, &data_obj)) {
        return NULL;
    }

    PyArrayObject *resid = (PyArrayObject *)PyArray_FROM_OTF(resid_obj, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *V = (PyArrayObject *)PyArray_FROM_OTF(v_obj, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *ipntr_a = (PyArrayObject *)PyArray_FROM_OTF(ipntr_obj, NPY_INT32, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *workd_a = (PyArrayObject *)PyArray_FROM_OTF(workd_obj, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *workl_a = (PyArrayObject *)PyArray_FROM_OTF(workl_obj, NPY_FLOAT64, NPY_ARRAY_INOUT_ARRAY2);
    PyArrayObject *indptr_a = (PyArrayObject *)PyArray_FROM_OTF(indptr_obj, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *indices_a = (PyArrayObject *)PyArray_FROM_OTF(indices_obj, NPY_INT32, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *data_a = (PyArrayObject *)PyArray_FROM_OTF(data_obj, NPY_FLOAT64, NPY_ARRAY_IN_ARRAY);
    if (!resid || !V || !ipntr_a || !workd_a || !workl_a || !indptr_a || !indices_a || !data_a) {
        Py_XDECREF(resid); Py_XDECREF(V); Py_XDECREF(ipntr_a); Py_XDECREF(workd_a);
        Py_XDECREF(workl_a); Py_XDECREF(indptr_a); Py_XDECREF(indices_a); Py_XDECREF(data_a);
        return NULL;
    }

    npy_intp n = PyArray_DIM(resid, 0);
    const npy_int32 *indptr = (const npy_int32 *)PyArray_DATA(indptr_a);
    const npy_int32 *indices = (const npy_int32 *)PyArray_DATA(indices_a);
    const double *data = (const double *)PyArray_DATA(data_a);
    double *workd = (double *)PyArray_DATA(workd_a);
    int *ipntr = (int *)PyArray_DATA(ipntr_a);
    double *ytmp = (double *)malloc(sizeof(double) * (size_t)n);
    if (!ytmp) {
        PyErr_NoMemory();
        goto cleanup;
    }

    PyObject *ido_key = PyUnicode_InternFromString("ido");
    PyObject *info_key = PyUnicode_InternFromString("info");
    if (!ido_key || !info_key) goto cleanup;

    long long steps = 0;
    while (1) {
        PyObject *ret = PyObject_CallFunctionObjArgs(wrap, state, resid, V, ipntr_a, workd_a, workl_a, NULL);
        if (!ret) goto cleanup;
        Py_DECREF(ret);
        ++steps;
        PyObject *ido_obj = PyDict_GetItem(state, ido_key);
        int ido = (int)PyLong_AsLong(ido_obj);
        if (ido == 1 || ido == -1 || ido == 5) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            csr_matvec(n, indptr, indices, data, workd + x0, ytmp);
            memcpy(workd + y0, ytmp, sizeof(double) * (size_t)n);
        } else if (ido == 2) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            memcpy(workd + y0, workd + x0, sizeof(double) * (size_t)n);
        } else {
            break;
        }
        if (steps > 10000000) {
            PyErr_SetString(PyExc_RuntimeError, "arpack did not converge");
            goto cleanup;
        }
    }
    {
        PyObject *info_obj = PyDict_GetItem(state, info_key);
        int info = info_obj ? (int)PyLong_AsLong(info_obj) : -1;
        free(ytmp);
        Py_DECREF(resid); Py_DECREF(V); Py_DECREF(ipntr_a); Py_DECREF(workd_a);
        Py_DECREF(workl_a); Py_DECREF(indptr_a); Py_DECREF(indices_a); Py_DECREF(data_a);
        return PyLong_FromLong(info);
    }

cleanup:
    free(ytmp);
    Py_XDECREF(resid); Py_XDECREF(V); Py_XDECREF(ipntr_a); Py_XDECREF(workd_a);
    Py_XDECREF(workl_a); Py_XDECREF(indptr_a); Py_XDECREF(indices_a); Py_XDECREF(data_a);
    return NULL;
}

