def pairs(ev, evec):
    return sorted(zip(ev, evec.T), key=lambda p: -abs(p[0]))

def sim(A, ncv):
    n = A.shape[0]
    v0 = np.ones(n, dtype=A.dtype)
    ev, evec = eigs(A, k=5, v0=v0, ncv=20, maxiter=n*200)
