    p1 = pairs(ev, evec)
    p2 = pairs(ev2, evec2)
    return min(abs(np.vdot(a[1], b[1]))/(np.linalg.norm(a[1])*np.linalg.norm(b[1])) for a,b in zip(p1, p2))

